import React, { createContext, useContext, useEffect, useState } from 'react'
import ReactDOM from 'react-dom/client'
import { BrowserRouter, Navigate, Route, Routes, useLocation, useNavigate } from 'react-router-dom'
import axios from 'axios'
import { LayoutDashboard, FilePlus2, ClipboardCheck, CalendarDays, Bell, Network, Users, ShieldCheck, LogOut, Menu, X, ChevronLeft, Search, Plus, CheckCircle2, Clock3, AlertCircle, ArrowRight, Building2, UserRound, Eye, Paperclip, Save } from 'lucide-react'
import './styles.css'
import { CreateMultiDirectorate, MultiDirectorateDetail, MultiDirectorateScheduling } from './flow03'
import { CreateHighAuthority, HighAuthorityDetail, HighAuthorityScheduling, HighAuthorityInbox } from './flow04'
import { CreateMultiHighAuthority, MultiHighAuthorityDetail, MultiHighAuthorityScheduling, MultiHighAuthorityInbox } from './flow05'
import { CreateAuthorityInitiated, AuthorityInitiatedDetail, AuthorityInitiatedScheduling, AuthorityInitiatedInbox } from './flow06'
import { MeetingRescheduleWorkspace } from './flow07'
import { MeetingParticipantChangeWorkspace } from './flow08'

type User = { id:number; name:string; email:string; employee?: { full_name:string; unit?: {name:string} }; roles?: {role:string; unit?: {name:string}}[] }
type AuthState = { user: User|null; loading:boolean; login:(email:string,password:string)=>Promise<void>; logout:()=>Promise<void> }
const api = axios.create({ baseURL: '/api' })
api.interceptors.request.use(config => { const token = localStorage.getItem('amms_token'); if (token) config.headers.Authorization = `Bearer ${token}`; return config })
const AuthContext = createContext<AuthState>({user:null,loading:true,login:async()=>{},logout:async()=>{}})
const useAuth = () => useContext(AuthContext)
const apiData = (res:any) => res.data?.data ?? res.data
const apiPage = (res:any) => { const body=res.data; const payload=body?.data ?? body; return Array.isArray(payload) ? {data:payload,meta:body?.meta||null,links:body?.links||null} : payload }
const statusLabels: Record<string,string> = {DRAFT:'پیش‌نویس',PENDING_INTERNAL_APPROVAL:'منتظر تأیید',RETURNED_FOR_REVISION:'برگشت جهت اصلاح',REJECTED:'رد شده',APPROVED:'تأیید شده',SCHEDULING:'در حال زمان‌بندی',SCHEDULE_CONFIRMED:'زمان‌بندی نهایی',CONVERTED_TO_MEETING:'تبدیل به جلسه',PENDING_REQUESTER_APPROVAL:'منتظر تأیید ریاست درخواست‌کننده',RETURNED_TO_REQUESTER:'برگشت به درخواست‌کننده',REQUESTER_APPROVED:'تأیید ریاست درخواست‌کننده',REJECTED_INTERNAL:'رد داخلی',SUBMITTED_TO_TARGET:'ارسال‌شده به ریاست مقصد',UNDER_TARGET_REVIEW:'در حال بررسی ریاست مقصد',RETURNED_BY_TARGET:'برگشت از ریاست مقصد',RESUBMITTED_TO_TARGET:'ارسال مجدد به ریاست مقصد',TARGET_APPROVED:'تأیید ریاست مقصد',REJECTED_BY_TARGET:'رد توسط ریاست مقصد',BILATERAL_APPROVED:'تأیید دوطرفه',SUBMITTED_TO_TARGETS:'ارسال‌شده به ریاست‌های مقصد',UNDER_MULTI_TARGET_REVIEW:'در حال بررسی ریاست‌های مقصد',TARGET_ACTION_REQUIRED:'نیازمند اصلاح از سوی ریاست‌های مقصد',MULTILATERAL_APPROVED:'تأیید چندجانبه',SUBMITTED_TO_PARTICIPATING_DIRECTORATES:'ارسال‌شده به ریاست‌های اشتراک‌کننده',UNDER_PARTICIPATING_REVIEW:'در حال بررسی ریاست‌های اشتراک‌کننده',DIRECTORATE_ACTION_REQUIRED:'نیازمند اصلاح از سوی ریاست اشتراک‌کننده',DIRECTORATES_APPROVED:'تأیید همهٔ ریاست‌ها',REJECTED_BY_PARTICIPATING_DIRECTORATE:'رد توسط ریاست اشتراک‌کننده',SUBMITTED_TO_AUTHORITY_OFFICE:'ارسال‌شده به دفتر مقام',UNDER_AUTHORITY_OFFICE_REVIEW:'در حال بررسی دفتر مقام',RETURNED_BY_AUTHORITY_OFFICE:'برگشت از دفتر مقام',PENDING_HIGH_AUTHORITY_DECISION:'منتظر تصمیم مقام عالی',RETURNED_BY_HIGH_AUTHORITY:'برگشت از مقام عالی',REJECTED_BY_HIGH_AUTHORITY:'رد توسط مقام عالی',HIGH_AUTHORITY_APPROVED:'تأیید مقام عالی',AUTHORITY_SCHEDULING:'در حال زمان‌بندی دفتر مقام',PENDING_HIGH_AUTHORITY_ISSUANCE:'منتظر صدور مقام عالی',RETURNED_FOR_AUTHORITY_DRAFT_CORRECTION:'برگشت برای اصلاح مسوده',ISSUED_BY_HIGH_AUTHORITY:'صادرشده توسط مقام عالی',DISTRIBUTED_TO_DIRECTORATES:'توزیع‌شده به ریاست‌ها',UNDER_DIRECTORATE_COORDINATION:'در حال هماهنگی ریاست‌ها',DIRECTORATE_CLARIFICATION_REQUIRED:'نیازمند وضاحت ریاست',PENDING_HIGH_AUTHORITY_REISSUANCE:'منتظر صدور مجدد مقام عالی',DIRECTORATES_ACKNOWLEDGED:'تأیید دریافت همهٔ ریاست‌ها'}
const purposeLabels: Record<string,string> = {DECISION:'تصمیم‌گیری',COORDINATION:'هماهنگی',CONSULTATION:'مشورت',REPORTING:'گزارش‌دهی',APPROVAL:'تأیید',FOLLOW_UP:'پیگیری',OTHER:'سایر'}
const priorityLabels: Record<string,string> = {NORMAL:'عادی',HIGH:'بلند',URGENT:'عاجل'}

function AuthProvider({children}:{children:React.ReactNode}) {
  const [user,setUser] = useState<User|null>(null); const [loading,setLoading] = useState(true)
  useEffect(()=>{ if(!localStorage.getItem('amms_token')) return setLoading(false); api.get('/me').then(r=>setUser(apiData(r))).catch(()=>localStorage.removeItem('amms_token')).finally(()=>setLoading(false)) },[])
  const login = async (email:string,password:string) => { const data=apiData(await api.post('/login',{email,password})); localStorage.setItem('amms_token',data.token); setUser(data.user) }
  const logout = async () => { try { await api.post('/logout') } finally { localStorage.removeItem('amms_token'); setUser(null) } }
  return <AuthContext.Provider value={{user,loading,login,logout}}>{children}</AuthContext.Provider>
}
function Protected({children}:{children:React.ReactNode}) { const {user,loading}=useAuth(); if(loading) return <div className="screen-center"><div className="spinner"/></div>; return user?<>{children}</>:<Navigate to="/login" replace/> }
function RoleGate({role,children}:{role:string;children:React.ReactNode}) { const {user}=useAuth(); return user?.roles?.some(r=>r.role===role)||user?.roles?.some(r=>r.role==='SYSTEM_ADMIN')?<>{children}</>:null }

const navItems = [
  {to:'/dashboard',label:'داشبورد',icon:LayoutDashboard}, {to:'/meeting-requests',label:'درخواست‌های جلسه',icon:FilePlus2}, {to:'/incoming-meeting-requests',label:'درخواست‌های وارده',icon:ClipboardCheck,roles:['EXECUTIVE_MANAGEMENT','DIRECTOR','MEETING_COORDINATOR','SYSTEM_ADMIN']},   {to:'/incoming-high-authority',label:'درخواست‌های دفتر مقام',icon:ShieldCheck,roles:['AUTHORITY_OFFICE','EXECUTIVE_SECRETARY','HIGH_AUTHORITY','SYSTEM_ADMIN']}, {to:'/incoming-authority-initiated',label:'دستورهای ابتکاری مقام',icon:ShieldCheck,roles:['AUTHORITY_OFFICE','EXECUTIVE_SECRETARY','HIGH_AUTHORITY','SYSTEM_ADMIN']},
 {to:'/approvals',label:'تأیید درخواست‌ها',icon:ClipboardCheck,role:'DIRECTOR'}, {to:'/meetings',label:'جلسات',icon:CalendarDays}, {to:'/notifications',label:'اعلان‌ها',icon:Bell}, {to:'/admin/organization',label:'ساختار تشکیلاتی',icon:Network,role:'SYSTEM_ADMIN'}, {to:'/admin/employees',label:'کارمندان',icon:Users,role:'SYSTEM_ADMIN'}, {to:'/admin/roles',label:'کاربران و صلاحیت‌ها',icon:ShieldCheck,role:'SYSTEM_ADMIN'},
]
function Shell({children}:{children:React.ReactNode}) { const {user,logout}=useAuth(); const [mobile,setMobile]=useState(false); const location=useLocation(); const navigate=useNavigate(); return <div className="app-shell"><aside className={`sidebar ${mobile?'open':''}`}><div className="brand"><div className="brand-mark">ا</div><div><strong>جلسات اداری</strong><span>AMMS · اداره نمونه</span></div><button className="icon-button mobile-close" onClick={()=>setMobile(false)}><X size={18}/></button></div><div className="user-summary"><div className="avatar">{user?.name?.slice(0,1)}</div><div><strong>{user?.name}</strong><span>{user?.roles?.[0]?.role==='DIRECTOR'?'رئیس ریاست':user?.roles?.[0]?.role==='EXECUTIVE_MANAGEMENT'?'مدیریت اجرائیه':'کاربر سیستم'}</span></div></div><nav>{navItems.map(item=>{const Icon=item.icon; const allowed=(!item.role&&!item.roles)||((item.role?user?.roles?.some(r=>r.role===item.role):item.roles?.some((role:string)=>user?.roles?.some(r=>r.role===role)))||user?.roles?.some(r=>r.role==='SYSTEM_ADMIN')); return allowed?<button key={item.to} className={location.pathname===item.to||location.pathname.startsWith(item.to+'/')?'active':''} onClick={()=>{navigate(item.to);setMobile(false)}}><Icon size={18}/><span>{item.label}</span></button>:null})}</nav><div className="sidebar-footer"><div className="security-note"><ShieldCheck size={16}/><span>محیط داخلی مصئون</span></div><button className="logout" onClick={logout}><LogOut size={17}/> خروج از سیستم</button></div></aside><div className="main-area"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setMobile(true)}><Menu size={21}/></button><div className="breadcrumb">اداره نمونه <ChevronLeft size={14}/> {location.pathname==='/dashboard'?'داشبورد':'مدیریت جلسات'}</div><div className="top-actions"><button className="icon-button" onClick={()=>navigate('/notifications')}><Bell size={19}/><span className="notification-dot"/></button><div className="top-user"><span>{user?.name}</span><div className="avatar small">{user?.name?.slice(0,1)}</div></div></div></header><main className="content">{children}</main></div></div> }
function PageTitle({eyebrow,title,description,action}:{eyebrow?:string;title:string;description?:string;action?:React.ReactNode}) { return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description&&<p>{description}</p>}</div>{action}</div> }
function StatCard({label,value,icon:Icon,tone='blue',hint}:{label:string;value:string|number;icon:any;tone?:string;hint?:string}) { return <div className={`stat-card ${tone}`}><div className="stat-icon"><Icon size={20}/></div><div><span>{label}</span><strong>{value}</strong>{hint&&<small>{hint}</small>}</div></div> }
function Dashboard() { const [data,setData]=useState<any>({}); const [requests,setRequests]=useState<any[]>([]); useEffect(()=>{api.get('/dashboard').then(r=>setData(apiData(r)));api.get('/meeting-requests').then(r=>setRequests(apiPage(r).data||[]))},[]); return <><PageTitle eyebrow="نمای کلی سیستم" title="داشبورد مدیریتی" description="وضعیت درخواست‌ها و جلسات حوزه صلاحیت شما در یک نگاه." action={<button className="button primary" onClick={()=>location.href='/meeting-requests/create'}><Plus size={18}/> درخواست جدید</button>}/><div className="stats-grid"><StatCard label="درخواست‌های من" value={data.my_requests||0} icon={FilePlus2}/><StatCard label="منتظر تأیید" value={data.pending_approval||0} icon={Clock3} tone="amber"/><StatCard label="برگشتی جهت اصلاح" value={data.returned||0} icon={AlertCircle} tone="red"/><StatCard label="جلسات آینده" value={data.upcoming_meetings||0} icon={CalendarDays} tone="green"/></div><div className="dashboard-grid"><section className="panel"><div className="panel-head"><div><span className="eyebrow">فعالیت اخیر</span><h2>درخواست‌های اخیر</h2></div><a href="/meeting-requests">مشاهده همه <ArrowRight size={15}/></a></div><div className="mini-list">{requests.slice(0,5).map((r:any)=><a className="mini-row" key={r.id} href={`/meeting-requests/${r.id}`}><div><strong>{r.subject}</strong><span>{r.request_number||'پیش‌نویس'} · {r.requesting_unit?.name}</span></div><StatusBadge value={r.status}/></a>)}{requests.length===0&&<EmptyState text="هنوز درخواستی ثبت نشده است."/>}</div></section><section className="panel accent-panel"><div className="panel-head"><div><span className="eyebrow">راهنمای جریان کاری</span><h2>FLOW-01</h2></div><CheckCircle2 size={22}/></div><p>درخواست داخلی ریاست پس از ثبت توسط مدیریت اجرائیه، برای بررسی رئیس ریاست ارسال شده و سپس در فضای جداگانه زمان‌بندی می‌گردد.</p><div className="flow-steps"><span>ثبت درخواست</span><i>←</i><span>تأیید ریاست</span><i>←</i><span>زمان‌بندی</span><i>←</i><span>ایجاد جلسه</span></div></section></div></> }
function StatusBadge({value}:{value:string}) { return <span className={`status ${value?.toLowerCase()}`}>{statusLabels[value]||value}</span> }
function EmptyState({text}:{text:string}) { return <div className="empty"><ClipboardCheck size={24}/><span>{text}</span></div> }

function Login() { const {user,login}=useAuth(); const navigate=useNavigate(); const [email,setEmail]=useState('tech.exec@example.test'); const [password,setPassword]=useState('ChangeMe!2026'); const [error,setError]=useState(''); const [busy,setBusy]=useState(false); if(user) return <Navigate to="/dashboard" replace/>; const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await login(email,password);navigate('/dashboard')}catch{setError('ایمیل یا رمز عبور نادرست است.')}finally{setBusy(false)}}; return <div className="login-screen"><div className="login-aside"><div className="login-emblem">ا</div><h1>سیستم مدیریت<br/>جلسات اداری</h1><p>سامانه داخلی برای ثبت، بررسی، زمان‌بندی و مدیریت جلسات اداری ریاست‌ها.</p><div className="login-line"/><small>Administrative Meeting Management System</small></div><div className="login-card"><div className="mobile-brand"><div className="brand-mark">ا</div><strong>جلسات اداری</strong></div><span className="eyebrow">ورود به سامانه داخلی</span><h2>خوش آمدید</h2><p className="muted">برای ادامه، اطلاعات حساب خود را وارد نمایید.</p><form onSubmit={submit}><label>ایمیل کاربری<input type="email" value={email} onChange={e=>setEmail(e.target.value)} dir="ltr"/></label><label>رمز عبور<input type="password" value={password} onChange={e=>setPassword(e.target.value)} dir="ltr"/></label>{error&&<div className="form-error">{error}</div>}<button className="button primary full" disabled={busy}>{busy?'در حال ورود...':'ورود به سامانه'}<ArrowRight size={17}/></button></form><div className="login-help"><ShieldCheck size={16}/> دسترسی شما بر اساس نقش و حوزه تشکیلاتی کنترل می‌شود.</div></div></div> }

function Requests() { const [data,setData]=useState<any>({data:[]}); const [status,setStatus]=useState(''); const [search,setSearch]=useState(''); const load=()=>api.get('/meeting-requests',{params:{status:status||undefined,search:search||undefined}}).then(r=>setData(apiPage(r))); useEffect(()=>{load()},[status]); return <><PageTitle eyebrow="مدیریت گردش کار" title="درخواست‌های جلسه" description="درخواست‌های ثبت‌شده در حوزه دسترسی شما." action={<div className="page-actions"><a className="button secondary" href="/meeting-requests/create">درخواست داخلی</a><a className="button primary" href="/meeting-requests/create-inter-directorate"><Plus size={18}/> جلسه بین دو ریاست</a><a className="button primary" href="/meeting-requests/create-multi-directorate"><Plus size={18}/> جلسه چندریاستی</a><a className="button primary" href="/meeting-requests/create-high-authority"><Plus size={18}/> جلسه با مقام عالی</a><a className="button primary" href="/meeting-requests/create-multi-high-authority"><Plus size={18}/> چندریاستی با مقام</a><a className="button primary" href="/meeting-requests/create-authority-initiated"><Plus size={18}/> جلسه به ابتکار مقام</a></div>}/><div className="toolbar"><div className="search"><Search size={17}/><input placeholder="جستجو بر اساس موضوع یا شماره..." value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==='Enter'&&load()}/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">همه وضعیت‌ها</option>{Object.entries(statusLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select><select><option>همه اولویت‌ها</option><option value="NORMAL">عادی</option><option value="HIGH">بلند</option><option value="URGENT">عاجل</option></select></div><div className="panel table-panel"><table><thead><tr><th>شماره درخواست</th><th>موضوع</th><th>ریاست</th><th>اولویت</th><th>وضعیت</th><th>تاریخ ایجاد</th><th>عملیات</th></tr></thead><tbody>{(data.data||[]).map((r:any)=><tr key={r.id}><td className="mono">{r.request_number||'—'}</td><td><a className="table-link" href={`/meeting-requests/${r.id}`}>{r.subject}</a><small>{purposeLabels[r.purpose]}</small></td><td>{r.requesting_unit?.name||'—'}</td><td><span className={`priority ${r.priority?.toLowerCase()}`}>{priorityLabels[r.priority]}</span></td><td><StatusBadge value={r.status}/></td><td>{new Date(r.created_at).toLocaleDateString('fa-AF')}</td><td><a className="icon-button" href={`/meeting-requests/${r.id}`}><Eye size={17}/></a></td></tr>)}</tbody></table>{(data.data||[]).length===0&&<EmptyState text="درخواستی با این مشخصات یافت نشد."/>}</div></> }

function IncomingRequests() { const [data,setData]=useState<any>({data:[]}); const [status,setStatus]=useState(''); const load=()=>Promise.all([api.get('/incoming-meeting-requests',{params:{status:status||undefined}}),api.get('/incoming-multi-directorate-meeting-requests',{params:{status:status||undefined}})]).then(([a,b])=>{const left=apiPage(a).data||[];const right=apiPage(b).data||[];setData({data:[...left,...right].sort((x:any,y:any)=>String(y.created_at).localeCompare(String(x.created_at)))})}); useEffect(()=>{load()},[status]); return <><PageTitle eyebrow="ریاست مقصد" title="درخواست‌های وارده" description="درخواست‌هایی که پس از تأیید ریاست درخواست‌کننده به حوزهٔ شما ارسال شده‌اند."/><div className="toolbar"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">همه وضعیت‌ها</option>{Object.entries(statusLabels).filter(([k])=>k.includes('TARGET')||k.includes('BILATERAL')||k==='SUBMITTED_TO_TARGET'||k==='UNDER_TARGET_REVIEW').map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></div><div className="panel table-panel"><table><thead><tr><th>شماره درخواست</th><th>ریاست درخواست‌کننده</th><th>موضوع</th><th>اولویت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>{(data.data||[]).map((r:any)=><tr key={r.id}><td className="mono">{r.request_number||'—'}</td><td>{r.units?.find((u:any)=>u.role==='REQUESTER')?.unit?.name||r.requesting_unit?.name||'—'}</td><td><a className="table-link" href={`/meeting-requests/${r.id}`}>{r.subject}</a></td><td><span className={`priority ${r.priority?.toLowerCase()}`}>{priorityLabels[r.priority]}</span></td><td><StatusBadge value={r.status}/></td><td><a className="button small primary" href={`/meeting-requests/${r.id}`}>بررسی <Eye size={14}/></a></td></tr>)}</tbody></table>{!(data.data||[]).length&&<EmptyState text="درخواست وارده‌ای در حوزهٔ صلاحیت شما وجود ندارد."/>}</div></> }

function CreateInterDirectorateRequest() { const navigate=useNavigate(); const [units,setUnits]=useState<any[]>([]);const [employees,setEmployees]=useState<any[]>([]);const [form,setForm]=useState<any>({requesting_unit_id:'',target_unit_id:'',subject:'',purpose:'COORDINATION',description:'',priority:'NORMAL',preferred_date:'',preferred_start_time:'',estimated_duration_minutes:60,proposed_location:'',participant_ids:[]});const [error,setError]=useState('');useEffect(()=>{api.get('/organizational-units').then(r=>setUnits(apiData(r)));api.get('/employees').then(r=>setEmployees(apiData(r)))},[]);const save=async(submit:boolean)=>{try{const item=apiData(await api.post('/meeting-requests/inter-directorate',form));if(submit) await api.post(`/meeting-requests/${item.id}/submit-inter-directorate`);navigate(`/meeting-requests/${item.id}`)}catch(e:any){setError(e.response?.data?.message||'ثبت درخواست بین‌ریاستی ممکن نیست.')}};const allowedEmployees=employees.filter(e=>{const selected=[String(form.requesting_unit_id),String(form.target_unit_id)];return selected.includes(String(e.organizational_unit_id))||selected.length===0});return <><PageTitle eyebrow="درخواست جدید" title="جلسه بین دو ریاست" description="جلسهٔ رسمی میان دو ریاست فعال در یک سازمان." action={<a className="button secondary" href="/meeting-requests">انصراف</a>}/><div className="form-layout"><section className="panel form-card"><div className="section-title"><span>طرف‌های جلسه</span><small>ریاست درخواست‌کننده و ریاست مقصد باید متفاوت باشند.</small></div><div className="form-grid"><label>ریاست درخواست‌کننده<select value={form.requesting_unit_id} onChange={e=>setForm({...form,requesting_unit_id:e.target.value,participant_ids:[]})}><option value="">انتخاب ریاست</option>{units.filter(u=>u.unit_type==='DIRECTORATE').map(u=><option value={u.id} key={u.id}>{u.name}</option>)}</select></label><label>ریاست مقصد<select value={form.target_unit_id} onChange={e=>setForm({...form,target_unit_id:e.target.value,participant_ids:[]})}><option value="">انتخاب ریاست مقصد</option>{units.filter(u=>u.unit_type==='DIRECTORATE'&&String(u.id)!==String(form.requesting_unit_id)).map(u=><option value={u.id} key={u.id}>{u.name}</option>)}</select></label></div><div className="section-title separated"><span>اطلاعات اصلی</span></div><div className="form-grid"><label>موضوع جلسه<input value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})} placeholder="عنوان رسمی جلسه"/></label><label>هدف جلسه<select value={form.purpose} onChange={e=>setForm({...form,purpose:e.target.value})}>{Object.entries(purposeLabels).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label><label>اولویت<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{Object.entries(priorityLabels).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label></div><label>شرح و توضیحات<textarea rows={4} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><div className="section-title separated"><span>پیشنهاد اولیهٔ زمان‌بندی</span></div><div className="form-grid three"><label>تاریخ<input type="date" value={form.preferred_date} onChange={e=>setForm({...form,preferred_date:e.target.value})}/></label><label>زمان آغاز<input type="time" value={form.preferred_start_time} onChange={e=>setForm({...form,preferred_start_time:e.target.value})}/></label><label>مدت (دقیقه)<input type="number" value={form.estimated_duration_minutes} onChange={e=>setForm({...form,estimated_duration_minutes:Number(e.target.value)})}/></label></div><label>محل پیشنهادی<input value={form.proposed_location} onChange={e=>setForm({...form,proposed_location:e.target.value})}/></label><div className="section-title separated"><span>اشتراک‌کنندگان پیشنهادی</span><small>درخواست‌کننده فقط پیشنهاد می‌دهد؛ هر ریاست فهرست نهایی خودش را تأیید می‌کند.</small></div><div className="participant-picker">{allowedEmployees.map(e=><label className="check-row" key={e.id}><input type="checkbox" checked={form.participant_ids.includes(e.id)} onChange={ev=>setForm({...form,participant_ids:ev.target.checked?[...form.participant_ids,e.id]:form.participant_ids.filter((id:number)=>id!==e.id)})}/><span>{e.full_name}</span><small>{e.unit?.name}</small></label>)}</div>{error&&<div className="form-error">{error}</div>}<div className="form-actions"><button className="button secondary" onClick={()=>save(false)}>ذخیرهٔ پیش‌نویس</button><button className="button primary" onClick={()=>save(true)}>ارسال برای تأیید داخلی <ArrowRight size={17}/></button></div></section><aside className="panel side-note"><Building2 size={22}/><h3>FLOW-02</h3><p>این درخواست تا زمانی که ریاست درخواست‌کننده تأیید نکند به ریاست مقصد نمایش داده نمی‌شود.</p><div className="note-line"><CheckCircle2 size={16}/> تأیید ریاست درخواست‌کننده</div><div className="note-line"><CheckCircle2 size={16}/> تأیید ریاست مقصد</div><div className="note-line"><CheckCircle2 size={16}/> زمان‌بندی مذاکره‌ای</div></aside></div></> }

function Flow02EditPanel({r,reload}:{r:any;reload:()=>void}) { const [form,setForm]=useState<any>({subject:r.subject||'',description:r.description||'',preferred_date:r.preferred_date?.slice(0,10)||'',preferred_start_time:r.preferred_start_time||'',estimated_duration_minutes:r.estimated_duration_minutes||60,proposed_location:r.proposed_location||''});const [file,setFile]=useState<File|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const saveChanges=async(submit:boolean)=>{setBusy(true);setError('');try{await api.put(`/meeting-requests/${r.id}`,form);if(file){const fd=new FormData();fd.append('attachment',file);await api.post(`/meeting-requests/${r.id}/attachments`,fd,{headers:{'Content-Type':'multipart/form-data'}})}if(submit) await api.post(`/meeting-requests/${r.id}/resubmit-to-target`);setFile(null);reload()}catch(e:any){setError(e.response?.data?.message||'ذخیره یا ارسال مجدد انجام نشد.')}finally{setBusy(false)}};return <div className="panel form-card flow02-edit"><div className="section-title"><span><Paperclip size={16}/> اصلاح و ضمیمهٔ درخواست</span><small>پس از برگشت مقصد، اصلاحات و ضمیمه‌ها قبل از ارسال مجدد ثبت می‌شوند.</small></div><div className="form-grid"><label>موضوع<input value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})}/></label><label>محل پیشنهادی<input value={form.proposed_location} onChange={e=>setForm({...form,proposed_location:e.target.value})}/></label></div><label>شرح اصلاح‌شده<textarea rows={4} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><div className="form-grid three"><label>تاریخ<input type="date" value={form.preferred_date} onChange={e=>setForm({...form,preferred_date:e.target.value})}/></label><label>زمان آغاز<input type="time" value={form.preferred_start_time} onChange={e=>setForm({...form,preferred_start_time:e.target.value})}/></label><label>مدت<input type="number" value={form.estimated_duration_minutes} onChange={e=>setForm({...form,estimated_duration_minutes:Number(e.target.value)})}/></label></div><div className="file-input-row"><label><Paperclip size={16}/> ضمیمهٔ جدید<input type="file" onChange={e=>setFile(e.target.files?.[0]||null)}/></label>{file&&<span>{file.name}</span>}</div>{(r.attachments||[]).length>0&&<div className="attachment-list">{r.attachments.map((a:any)=><a key={a.id} href={`/api/meeting-request-attachments/${a.id}/download`} target="_blank" rel="noreferrer"><Paperclip size={14}/>{a.original_name}</a>)}</div>}{error&&<div className="form-error">{error}</div>}<div className="form-actions"><button className="button secondary" disabled={busy} onClick={()=>saveChanges(false)}><Save size={16}/> ذخیرهٔ اصلاحات</button><button className="button primary" disabled={busy} onClick={()=>saveChanges(true)}>{busy?'در حال ذخیره...':'ذخیره و ارسال مجدد'} <ArrowRight size={16}/></button></div></div> }

function Flow02Detail({r,reload}:{r:any;reload:()=>void}) { const [reason,setReason]=useState('');const action=async(url:string,body?:any)=>{try{await api.post(`/meeting-requests/${r.id}/${url}`,body);setReason('');reload()}catch(e:any){alert(e.response?.data?.message||'عملیات انجام نشد.')}};const requester=r.units?.find((u:any)=>u.role==='REQUESTER');const target=r.units?.find((u:any)=>u.role==='TARGET');const nominations=r.nominations||[];return <><PageTitle eyebrow={`${r.request_number||'پیش‌نویس'} · جلسه بین دو ریاست`} title={r.subject} description={`${requester?.unit?.name||r.requesting_unit?.name||'—'} ↔ ${target?.unit?.name||'—'}`} action={<div className="page-actions"><StatusBadge value={r.status}/><a className="button secondary" href="/meeting-requests">بازگشت به فهرست</a></div>}/><div className="detail-grid"><section className="detail-main"><div className="panel"><div className="detail-header"><div><span className="eyebrow">مشخصات درخواست بین‌ریاستی</span><h2>{r.subject}</h2></div><Building2 size={22}/></div><div className="info-grid"><div><span>ریاست درخواست‌کننده</span><strong>{requester?.unit?.name||r.requesting_unit?.name}</strong></div><div><span>ریاست مقصد</span><strong>{target?.unit?.name||'—'}</strong></div><div><span>هدف جلسه</span><strong>{purposeLabels[r.purpose]||r.purpose}</strong></div><div><span>اولویت</span><strong>{priorityLabels[r.priority]}</strong></div><div><span>تأیید درخواست‌کننده</span><strong>{r.requester_approved_at?'تأیید شده':'در انتظار'}</strong></div><div><span>تأیید مقصد</span><strong>{r.target_approved_at?'تأیید شده':'در انتظار'}</strong></div><div><span>زمان پیشنهادی</span><strong>{r.preferred_date?new Date(r.preferred_date).toLocaleDateString('fa-AF'):'تعیین نشده'} {r.preferred_start_time||''}</strong></div><div><span>محل پیشنهادی</span><strong>{r.proposed_location||'تعیین نشده'}</strong></div></div>{r.description&&<div className="description-block"><span>شرح</span><p>{r.description}</p></div>}</div>{r.status==='RETURNED_BY_TARGET'&&<Flow02EditPanel r={r} reload={reload}/>}<div className="panel"><div className="panel-head"><div><span className="eyebrow">اشتراک‌کنندگان نهایی</span><h2>تفکیک دو ریاست</h2></div><Users size={20}/></div><div className="two-column-cards"><div className="subpanel"><strong>{requester?.unit?.name||'ریاست درخواست‌کننده'}</strong>{nominations.filter((n:any)=>n.nominated_by_unit_id===requester?.organizational_unit_id).map((n:any)=><div className="person-row" key={n.id}><div className="avatar tiny">{n.employee?.full_name?.slice(0,1)}</div><div><strong>{n.employee?.full_name}</strong><span>{n.nomination_status==='CONFIRMED'?'تأیید نهایی':'نامزدشده'}</span></div></div>)}</div><div className="subpanel"><strong>{target?.unit?.name||'ریاست مقصد'}</strong>{nominations.filter((n:any)=>n.nominated_by_unit_id===target?.organizational_unit_id).map((n:any)=><div className="person-row" key={n.id}><div className="avatar tiny">{n.employee?.full_name?.slice(0,1)}</div><div><strong>{n.employee?.full_name}</strong><span>{n.nomination_status==='CONFIRMED'?'تأیید نهایی':'نامزدشده'}</span></div></div>)}</div></div></div>{(r.schedule_proposals||[]).length>0&&<div className="panel"><div className="panel-head"><div><span className="eyebrow">مذاکرهٔ زمان‌بندی</span><h2>تاریخچهٔ پیشنهادها</h2></div><CalendarDays size={20}/></div>{r.schedule_proposals.map((p:any)=><div className={`proposal-row ${p.status==='ACCEPTED'?'current':''}`} key={p.id}><div><strong>{p.proposed_by_unit?.name||'ریاست'}</strong><span>{new Date(p.meeting_date).toLocaleDateString('fa-AF')} · {p.start_time} تا {p.end_time} · {p.location}</span></div><span className="tag">{p.status==='ACCEPTED'?'پذیرفته‌شده':p.status==='SUPERSEDED'?'منسوخ':'پیشنهاد'}</span></div>)}</div>}</section><aside className="detail-side"><div className="panel action-panel"><span className="eyebrow">اقدامات FLOW-02</span><h3>عملیات مجاز</h3>{r.status==='DRAFT'&&<button className="button primary full" onClick={()=>action('submit-inter-directorate')}>ارسال برای تأیید داخلی</button>}{r.status==='PENDING_REQUESTER_APPROVAL'&&<><button className="button success full" onClick={()=>action('requester-approve')}>تأیید ریاست درخواست‌کننده</button><textarea placeholder="دلیل برگشت یا رد" value={reason} onChange={e=>setReason(e.target.value)}/><button className="button warning full" onClick={()=>action('requester-return',{reason})}>برگشت جهت اصلاح</button><button className="button danger full" onClick={()=>action('requester-reject',{reason})}>رد داخلی</button></>}{r.status==='SUBMITTED_TO_TARGET'&&<button className="button primary full" onClick={()=>action('target-review')}>آغاز بررسی ریاست مقصد</button>}{r.status==='UNDER_TARGET_REVIEW'&&<><button className="button success full" onClick={()=>action('target-approve')}>تأیید ریاست مقصد</button><textarea placeholder="دلیل وضاحت یا رد" value={reason} onChange={e=>setReason(e.target.value)}/><button className="button warning full" onClick={()=>action('target-return',{reason})}>برگشت جهت وضاحت</button><button className="button danger full" onClick={()=>action('target-reject',{reason})}>رد توسط مقصد</button></>}{r.status==='RETURNED_BY_TARGET'&&<div className="action-hint"><Paperclip size={16}/> اصلاحات و ارسال مجدد از پنل جزئیات انجام می‌شود.</div>}{r.status==='BILATERAL_APPROVED'&&<button className="button primary full" onClick={()=>action('start-inter-directorate-scheduling')}>آغاز مذاکرهٔ زمان‌بندی</button>}{['SCHEDULING','SCHEDULE_CONFIRMED'].includes(r.status)&&<a className="button primary full" href={`/meeting-requests/${r.id}/scheduling`}>ورود به فضای زمان‌بندی</a>}{r.meeting&&<a className="button secondary full" href={`/meetings/${r.meeting.id}`}>مشاهدهٔ جلسهٔ ایجادشده</a>}</div><div className="panel timeline"><div className="panel-head"><div><span className="eyebrow">تاریخچهٔ غیرقابل حذف</span><h3>خط زمانی دوطرفه</h3></div><Clock3 size={19}/></div>{(r.actions||[]).map((a:any)=><div className="timeline-item" key={a.id}><div className="timeline-dot"/><div><strong>{a.action}</strong><span>{a.actor?.name} · {new Date(a.created_at).toLocaleString('fa-AF')}</span>{a.comment&&<p>{a.comment}</p>}</div></div>)}</div></aside></div></> }

function CreateRequest() { const navigate=useNavigate(); const [units,setUnits]=useState<any[]>([]);const [employees,setEmployees]=useState<any[]>([]);const [form,setForm]=useState<any>({requesting_unit_id:'',subject:'',purpose:'COORDINATION',description:'',priority:'NORMAL',preferred_date:'',preferred_start_time:'',estimated_duration_minutes:60,proposed_location:'',participant_ids:[]});const [error,setError]=useState('');useEffect(()=>{api.get('/organizational-units').then(r=>setUnits(apiData(r)));api.get('/employees').then(r=>setEmployees(apiData(r)))},[]);const save=async(submit:boolean)=>{try{const r=await api.post('/meeting-requests',form);const item=apiData(r); if(submit) await api.post(`/meeting-requests/${item.id}/submit`);navigate(`/meeting-requests/${item.id}`)}catch(e:any){setError(e.response?.data?.message||'ثبت درخواست ممکن نیست.')}};return <><PageTitle eyebrow="درخواست جدید" title="ثبت درخواست جلسه داخلی" description="این درخواست پس از ثبت برای بررسی رئیس ریاست ارسال می‌شود." action={<a className="button secondary" href="/meeting-requests">انصراف</a>}/><div className="form-layout"><section className="panel form-card"><div className="section-title"><span>اطلاعات اصلی</span><small>تمام قواعد در سمت سرور بررسی می‌شود.</small></div><div className="form-grid"><label>ریاست درخواست‌کننده<select value={form.requesting_unit_id} onChange={e=>setForm({...form,requesting_unit_id:e.target.value})}><option value="">انتخاب ریاست</option>{units.filter(u=>u.unit_type==='DIRECTORATE').map(u=><option value={u.id} key={u.id}>{u.name}</option>)}</select></label><label>موضوع جلسه<input value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})} placeholder="عنوان رسمی جلسه"/></label><label>هدف جلسه<select value={form.purpose} onChange={e=>setForm({...form,purpose:e.target.value})}>{Object.entries(purposeLabels).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label><label>اولویت<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{Object.entries(priorityLabels).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label></div><label>شرح و توضیحات<textarea rows={5} value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="جزئیات لازم درباره موضوع جلسه..."/></label><div className="section-title separated"><span>زمان و مکان پیشنهادی</span></div><div className="form-grid three"><label>تاریخ پیشنهادی<input type="date" value={form.preferred_date} onChange={e=>setForm({...form,preferred_date:e.target.value})}/></label><label>زمان آغاز<input type="time" value={form.preferred_start_time} onChange={e=>setForm({...form,preferred_start_time:e.target.value})}/></label><label>مدت (دقیقه)<input type="number" value={form.estimated_duration_minutes} onChange={e=>setForm({...form,estimated_duration_minutes:Number(e.target.value)})}/></label></div><label>محل پیشنهادی<input value={form.proposed_location} onChange={e=>setForm({...form,proposed_location:e.target.value})} placeholder="مثلاً: اتاق جلسات تکنالوژی"/></label><div className="section-title separated"><span>اشتراک‌کنندگان پیشنهادی</span><small>فقط کارمندان ریاست و واحدهای فرعی آن مجاز هستند.</small></div><div className="participant-picker">{employees.map(e=><label className="check-row" key={e.id}><input type="checkbox" checked={form.participant_ids.includes(e.id)} onChange={ev=>setForm({...form,participant_ids:ev.target.checked?[...form.participant_ids,e.id]:form.participant_ids.filter((id:number)=>id!==e.id)})}/><span>{e.full_name}</span><small>{e.unit?.name}</small></label>)}</div>{error&&<div className="form-error">{error}</div>}<div className="form-actions"><button className="button secondary" onClick={()=>save(false)}>ذخیره پیش‌نویس</button><button className="button primary" onClick={()=>save(true)}>ارسال برای تأیید <ArrowRight size={17}/></button></div></section><aside className="panel side-note"><Building2 size={22}/><h3>راهنمای ثبت درخواست</h3><p>در این مرحله جلسه ایجاد نمی‌شود. پس از تأیید رئیس ریاست، درخواست به فضای جداگانه زمان‌بندی منتقل خواهد شد.</p><div className="note-line"><CheckCircle2 size={16}/> بررسی صلاحیت درخواست‌کننده</div><div className="note-line"><CheckCircle2 size={16}/> کنترل مرز ریاست</div><div className="note-line"><CheckCircle2 size={16}/> ثبت تاریخچه غیرقابل حذف</div></aside></div></> }

function RequestDetail() { const id=location.pathname.split('/')[2];const [r,setR]=useState<any>(null);const [reason,setReason]=useState('');const navigate=useNavigate();const load=()=>api.get(`/meeting-requests/${id}`).then(x=>setR(apiData(x)));useEffect(()=>{load()},[id]);if(!r)return <div className="screen-center"><div className="spinner"/></div>;if(r.flow_type==='INTER_DIRECTORATE')return <Flow02Detail r={r} reload={load}/>;if(r.flow_type==='MULTI_DIRECTORATE')return <MultiDirectorateDetail/>;if(r.flow_type==='DIRECTORATE_WITH_HIGH_AUTHORITY')return <HighAuthorityDetail/>;if(r.flow_type==='MULTI_DIRECTORATE_WITH_HIGH_AUTHORITY')return <MultiHighAuthorityDetail/>;if(r.flow_type==='HIGH_AUTHORITY_INITIATED')return <AuthorityInitiatedDetail/>;const action=async(url:string,body?:any)=>{try{await api.post(`/meeting-requests/${id}/${url}`,body);load()}catch(e:any){alert(e.response?.data?.message||'عملیات انجام نشد.')}};return <><PageTitle eyebrow={r.request_number||'پیش‌نویس'} title={r.subject} description={`${r.requesting_unit?.name||''} · ${purposeLabels[r.purpose]||r.purpose}`} action={<div className="page-actions"><StatusBadge value={r.status}/><a className="button secondary" href="/meeting-requests">بازگشت به فهرست</a></div>}/><div className="detail-grid"><section className="detail-main"><div className="panel"><div className="detail-header"><div><span className="eyebrow">مشخصات درخواست</span><h2>{r.subject}</h2></div><span className={`priority ${r.priority?.toLowerCase()}`}>{priorityLabels[r.priority]}</span></div><div className="info-grid"><div><span>هدف جلسه</span><strong>{purposeLabels[r.purpose]}</strong></div><div><span>ریاست درخواست‌کننده</span><strong>{r.requesting_unit?.name}</strong></div><div><span>ایجادکننده</span><strong>{r.creator?.name}</strong></div><div><span>زمان پیشنهادی</span><strong>{r.preferred_date?new Date(r.preferred_date).toLocaleDateString('fa-AF'):'تعیین نشده'} {r.preferred_start_time||''}</strong></div><div><span>محل پیشنهادی</span><strong>{r.proposed_location||'تعیین نشده'}</strong></div><div><span>مدت</span><strong>{r.estimated_duration_minutes?`${r.estimated_duration_minutes} دقیقه`:'تعیین نشده'}</strong></div></div>{r.description&&<div className="description-block"><span>شرح و توضیحات</span><p>{r.description}</p></div>}</div><div className="panel"><div className="panel-head"><div><span className="eyebrow">فهرست اشتراک‌کنندگان</span><h2>اشتراک‌کنندگان پیشنهادی</h2></div><Users size={20}/></div><div className="people-list">{(r.participants||[]).map((p:any)=><div className="person-row" key={p.id}><div className="avatar tiny">{p.employee?.full_name?.slice(0,1)}</div><div><strong>{p.employee?.full_name}</strong><span>{p.employee?.unit?.name}</span></div><span className="tag">{p.participant_type==='FINAL'?'نهایی':'پیشنهادی'}</span></div>)}</div></div></section><aside className="detail-side"><div className="panel action-panel"><span className="eyebrow">عملیات مجاز</span><h3>اقدامات گردش کار</h3>{r.status==='DRAFT'&&<><button className="button primary full" onClick={()=>action('submit')}>ارسال برای تأیید</button></>}{r.status==='RETURNED_FOR_REVISION'&&<button className="button primary full" onClick={()=>navigate(`/meeting-requests/${r.id}/edit`)}>اصلاح درخواست</button>}{r.status==='PENDING_INTERNAL_APPROVAL'&&<RoleGate role="DIRECTOR"><button className="button success full" onClick={()=>action('approve')}>تأیید درخواست</button><textarea placeholder="دلیل برگشت یا رد در صورت نیاز" value={reason} onChange={e=>setReason(e.target.value)}/><button className="button warning full" onClick={()=>action('return',{reason})}>برگشت جهت اصلاح</button><button className="button danger full" onClick={()=>action('reject',{reason})}>رد درخواست</button></RoleGate>}{r.status==='APPROVED'&&<button className="button primary full" onClick={()=>action('start-scheduling')}>شروع زمان‌بندی</button>}{r.status==='SCHEDULING'&&<button className="button primary full" onClick={()=>navigate(`/meeting-requests/${r.id}/scheduling`)}>ورود به فضای زمان‌بندی</button>}{r.status==='SCHEDULE_CONFIRMED'&&<button className="button primary full" onClick={()=>navigate(`/meeting-requests/${r.id}/scheduling`)}>نهایی‌سازی جلسه</button>}{r.meeting&&<a className="button secondary full" href={`/meetings/${r.meeting.id}`}>مشاهده جلسه ایجادشده</a>}</div><div className="panel timeline"><div className="panel-head"><div><span className="eyebrow">تاریخچه غیرقابل حذف</span><h3>خط زمانی درخواست</h3></div><Clock3 size={19}/></div>{(r.actions||[]).map((a:any)=><div className="timeline-item" key={a.id}><div className="timeline-dot"/><div><strong>{a.action==='CREATED'?'درخواست ایجاد شد':a.action==='SUBMITTED'?'درخواست برای تأیید ارسال شد':a.action==='RETURNED'?'درخواست جهت اصلاح برگشت داده شد':a.action==='RESUBMITTED'?'درخواست دوباره ارسال شد':a.action==='APPROVED'?'درخواست تأیید شد':a.action==='REJECTED'?'درخواست رد شد':a.action==='MEETING_CREATED'?'جلسه ایجاد گردید':a.action==='SCHEDULING_STARTED'?'زمان‌بندی آغاز شد':a.action==='SCHEDULE_CONFIRMED'?'زمان‌بندی نهایی شد':'درخواست اصلاح شد'}</strong><span>{a.actor?.name} · {new Date(a.created_at).toLocaleString('fa-AF')}</span>{a.comment&&<p>{a.comment}</p>}</div></div>)}</div></aside></div></> }

function Approvals() { const [data,setData]=useState<any>({data:[]});useEffect(()=>{api.get('/approvals').then(r=>setData(apiPage(r)))},[]);return <><PageTitle eyebrow="صلاحیت ریاست" title="درخواست‌های منتظر تأیید" description="فقط درخواست‌های ریاست‌های تحت صلاحیت شما نمایش داده می‌شود."/><div className="panel table-panel"><table><thead><tr><th>شماره</th><th>موضوع</th><th>درخواست‌کننده</th><th>اولویت</th><th>تاریخ</th><th>عملیات</th></tr></thead><tbody>{(data.data||[]).map((r:any)=><tr key={r.id}><td className="mono">{r.request_number}</td><td><a className="table-link" href={`/meeting-requests/${r.id}`}>{r.subject}</a></td><td>{r.creator?.name}</td><td><span className={`priority ${r.priority?.toLowerCase()}`}>{priorityLabels[r.priority]}</span></td><td>{new Date(r.created_at).toLocaleDateString('fa-AF')}</td><td><a className="button small primary" href={`/meeting-requests/${r.id}`}>بررسی <Eye size={14}/></a></td></tr>)}</tbody></table>{!(data.data||[]).length&&<EmptyState text="درخواست منتظر تأیید وجود ندارد."/>}</div></> }

function Scheduling() { const id=location.pathname.split('/')[2];const [r,setR]=useState<any>(null);const [employees,setEmployees]=useState<any[]>([]);const [form,setForm]=useState<any>({meeting_date:'',start_time:'09:00',end_time:'10:00',duration_minutes:60,location:'',chairperson_employee_id:'',participant_ids:[],agenda:''});useEffect(()=>{api.get(`/meeting-requests/${id}`).then(x=>{const d=apiData(x);setR(d);setForm((f:any)=>({...f,meeting_date:d.preferred_date?.slice(0,10)||'',start_time:d.preferred_start_time||f.start_time,duration_minutes:d.estimated_duration_minutes||60,location:d.proposed_location||''}))});api.get('/employees').then(x=>setEmployees(apiData(x)))},[id]);if(!r)return <div className="screen-center"><div className="spinner"/></div>;if(r.flow_type==='INTER_DIRECTORATE')return <Flow02Scheduling initial={r}/>;const confirm=async()=>{try{await api.post(`/meeting-requests/${id}/confirm-schedule`,form);await api.post(`/meeting-requests/${id}/finalize`,form);location.href=`/meeting-requests/${id}`}catch(e:any){alert(e.response?.data?.message||'اطلاعات زمان‌بندی کامل نیست.')}};return <><PageTitle eyebrow="فضای زمان‌بندی" title="نهایی‌سازی جلسه" description={`درخواست ${r.request_number} · ${r.subject}`} action={<a className="button secondary" href={`/meeting-requests/${id}`}>بازگشت</a>}/><div className="form-layout"><section className="panel form-card"><div className="approved-strip"><CheckCircle2 size={18}/><span>درخواست تأیید شده است؛ زمان و مکان جلسه هنوز نهایی نشده است.</span></div><div className="form-grid three"><label>تاریخ جلسه<input type="date" value={form.meeting_date} onChange={e=>setForm({...form,meeting_date:e.target.value})}/></label><label>زمان آغاز<input type="time" value={form.start_time} onChange={e=>setForm({...form,start_time:e.target.value})}/></label><label>زمان ختم<input type="time" value={form.end_time} onChange={e=>setForm({...form,end_time:e.target.value})}/></label></div><div className="form-grid"><label>محل جلسه<input value={form.location} onChange={e=>setForm({...form,location:e.target.value})}/></label><label>رئیس جلسه<select value={form.chairperson_employee_id} onChange={e=>setForm({...form,chairperson_employee_id:e.target.value})}><option value="">انتخاب رئیس جلسه</option>{employees.map(e=><option value={e.id} key={e.id}>{e.full_name} · {e.unit?.name}</option>)}</select></label></div><label>آجندا<textarea rows={5} value={form.agenda} onChange={e=>setForm({...form,agenda:e.target.value})} placeholder="آجندای رسمی جلسه را وارد نمایید..."/></label><div className="section-title separated"><span>اشتراک‌کنندگان نهایی</span></div><div className="participant-picker">{employees.map(e=><label className="check-row" key={e.id}><input type="checkbox" checked={form.participant_ids.includes(e.id)} onChange={ev=>setForm({...form,participant_ids:ev.target.checked?[...form.participant_ids,e.id]:form.participant_ids.filter((id:number)=>id!==e.id)})}/><span>{e.full_name}</span><small>{e.unit?.name}</small></label>)}</div><div className="form-actions"><button className="button primary" onClick={confirm}>نهایی‌سازی جلسه <CheckCircle2 size={17}/></button></div></section><aside className="panel side-note"><span className="eyebrow">مقادیر پیشنهادی</span><h3>مقایسه اطلاعات</h3><div className="compare"><span>تاریخ پیشنهادی</span><strong>{r.preferred_date?new Date(r.preferred_date).toLocaleDateString('fa-AF'):'—'}</strong></div><div className="compare"><span>زمان پیشنهادی</span><strong>{r.preferred_start_time||'—'}</strong></div><div className="compare"><span>محل پیشنهادی</span><strong>{r.proposed_location||'—'}</strong></div><p>تغییر برنامه در این مرحله بدون نیاز به تأیید مجدد مجاز است؛ تمام اشتراک‌کنندگان همچنان در مرز همان ریاست کنترل می‌شوند.</p></aside></div></> }

function Flow02Scheduling({initial}:{initial:any}) { const [r,setR]=useState<any>(initial);const [employees,setEmployees]=useState<any[]>([]);const [proposal,setProposal]=useState<any>({proposed_by_unit_id:'',meeting_date:'',start_time:'09:00',end_time:'10:00',location:'',comment:''});const [nomination,setNomination]=useState<any>({nominated_by_unit_id:'',employee_id:''});const [final,setFinal]=useState<any>({chairperson_employee_id:'',location:'',end_time:'11:00',agenda:''});const requester=r.units?.find((u:any)=>u.role==='REQUESTER');const target=r.units?.find((u:any)=>u.role==='TARGET');const load=()=>api.get(`/meeting-requests/${r.id}`).then(x=>setR(apiData(x)));useEffect(()=>{api.get('/employees').then(x=>setEmployees(apiData(x)));setProposal((p:any)=>({...p,proposed_by_unit_id:requester?.organizational_unit_id||''}));setNomination((n:any)=>({...n,nominated_by_unit_id:requester?.organizational_unit_id||''}))},[r.id,requester?.organizational_unit_id]);const call=async(url:string,body?:any)=>{try{await api.post(`/meeting-requests/${r.id}/${url}`,body);load()}catch(e:any){alert(e.response?.data?.message||'عملیات زمان‌بندی انجام نشد.')}};const propose=async()=>{await call('schedule-proposals',proposal)};const nominate=async()=>{await call('participant-nominations',nomination)};const finalize=async()=>{try{await api.post(`/meeting-requests/${r.id}/finalize-inter-directorate`,final);location.href=`/meeting-requests/${r.id}`}catch(e:any){alert(e.response?.data?.message||'پیش‌شرط‌های ایجاد جلسه تکمیل نیست.')}};return <><PageTitle eyebrow="مذاکرهٔ زمان‌بندی" title="فضای زمان‌بندی دوطرفه" description={`${r.request_number} · ${r.subject}`} action={<a className="button secondary" href={`/meeting-requests/${r.id}`}>بازگشت به درخواست</a>}/>{r.status==='BILATERAL_APPROVED'&&<div className="panel approved-strip"><CheckCircle2 size={18}/><span>هر دو ریاست موافقت کرده‌اند؛ مذاکرهٔ تاریخ و مکان را آغاز کنید.</span><button className="button primary" onClick={()=>call('start-inter-directorate-scheduling')}>آغاز مذاکره</button></div>}<div className="form-layout"><section className="detail-main"><div className="panel"><div className="panel-head"><div><span className="eyebrow">تاریخچهٔ مذاکره</span><h2>پیشنهادهای زمان‌بندی</h2></div><CalendarDays size={20}/></div>{(r.schedule_proposals||[]).map((p:any)=><div className={`proposal-row ${p.status==='ACCEPTED'?'current':''}`} key={p.id}><div><strong>{p.proposed_by_unit?.name||'ریاست'}</strong><span>{new Date(p.meeting_date).toLocaleDateString('fa-AF')} · {p.start_time} تا {p.end_time} · {p.location}</span>{p.comment&&<small>{p.comment}</small>}</div><div><span className="tag">{p.status==='ACCEPTED'?'پذیرفته‌شده':p.status==='SUPERSEDED'?'منسوخ':p.status==='COUNTER_PROPOSED'?'پیشنهاد متقابل':'پیشنهاد'}</span>{['PROPOSED','COUNTER_PROPOSED'].includes(p.status)&&<button className="button small secondary" onClick={()=>call(`schedule-proposals/${p.id}/accept`)}>پذیرش</button>}</div></div>)}{!(r.schedule_proposals||[]).length&&<EmptyState text="هنوز پیشنهاد زمانی ثبت نشده است."/>}</div>{['SCHEDULING'].includes(r.status)&&<div className="panel form-card"><div className="section-title"><span>ثبت پیشنهاد یا پیشنهاد متقابل</span><small>پیشنهادهای قبلی حذف نمی‌شوند.</small></div><div className="form-grid"><label>ریاست پیشنهاددهنده<select value={proposal.proposed_by_unit_id} onChange={e=>setProposal({...proposal,proposed_by_unit_id:e.target.value})}><option value="">انتخاب ریاست</option>{[requester,target].filter(Boolean).map((u:any)=><option value={u.organizational_unit_id} key={u.organizational_unit_id}>{u.unit?.name||'ریاست'}</option>)}</select></label><label>محل<input value={proposal.location} onChange={e=>setProposal({...proposal,location:e.target.value})}/></label></div><div className="form-grid three"><label>تاریخ<input type="date" value={proposal.meeting_date} onChange={e=>setProposal({...proposal,meeting_date:e.target.value})}/></label><label>از ساعت<input type="time" value={proposal.start_time} onChange={e=>setProposal({...proposal,start_time:e.target.value})}/></label><label>تا ساعت<input type="time" value={proposal.end_time} onChange={e=>setProposal({...proposal,end_time:e.target.value})}/></label></div><label>یادداشت<textarea value={proposal.comment} onChange={e=>setProposal({...proposal,comment:e.target.value})}/></label><button className="button primary" onClick={propose}>ثبت پیشنهاد</button></div>}<div className="panel form-card"><div className="section-title"><span>نامزدی اشتراک‌کنندگان</span><small>هر ریاست فقط فهرست خودش را مدیریت می‌کند.</small></div><div className="form-grid"><label>ریاست مالک فهرست<select value={nomination.nominated_by_unit_id} onChange={e=>setNomination({...nomination,nominated_by_unit_id:e.target.value})}><option value="">انتخاب ریاست</option>{[requester,target].filter(Boolean).map((u:any)=><option value={u.organizational_unit_id} key={u.organizational_unit_id}>{u.unit?.name||'ریاست'}</option>)}</select></label><label>کارمند<select value={nomination.employee_id} onChange={e=>setNomination({...nomination,employee_id:e.target.value})}><option value="">انتخاب کارمند</option>{employees.map(e=><option value={e.id} key={e.id}>{e.full_name} · {e.unit?.name}</option>)}</select></label></div><button className="button secondary" onClick={nominate}>ثبت نامزد</button><div className="form-actions"><button className="button success" onClick={()=>call('requester-participants/confirm')}>تأیید اشتراک‌کنندگان ریاست درخواست‌کننده</button><button className="button success" onClick={()=>call('target-participants/confirm')}>تأیید اشتراک‌کنندگان ریاست مقصد</button></div></div></section><aside className="detail-side"><div className="panel"><span className="eyebrow">وضعیت دو طرف</span><h3>{requester?.unit?.name||'درخواست‌کننده'}</h3><div className="compare"><span>تأیید فهرست</span><strong>{r.requester_participants_confirmed_at?'تکمیل شد':'در انتظار'}</strong></div><h3>{target?.unit?.name||'مقصد'}</h3><div className="compare"><span>تأیید فهرست</span><strong>{r.target_participants_confirmed_at?'تکمیل شد':'در انتظار'}</strong></div></div>{r.status==='SCHEDULING'&&r.requester_participants_confirmed_at&&r.target_participants_confirmed_at&&<div className="panel action-panel"><span className="eyebrow">تأیید نهایی</span><h3>هر دو فهرست تأیید شده‌اند</h3><p className="muted">زمان پذیرفته‌شدهٔ ریاست مالی آمادهٔ ثبت نهایی است.</p><button className="button primary full" onClick={()=>call('confirm-inter-directorate-schedule')}>تأیید زمان‌بندی نهایی</button></div>}{r.status==='SCHEDULE_CONFIRMED'&&<div className="panel form-card"><span className="eyebrow">ایجاد جلسه</span><h3>پیش‌شرط‌ها تکمیل شد</h3><label>رئیس جلسه<select value={final.chairperson_employee_id} onChange={e=>setFinal({...final,chairperson_employee_id:e.target.value})}><option value="">انتخاب رئیس جلسه</option>{employees.map(e=><option value={e.id} key={e.id}>{e.full_name} · {e.unit?.name}</option>)}</select></label><label>محل نهایی<input value={final.location} onChange={e=>setFinal({...final,location:e.target.value})}/></label><label>زمان ختم<input type="time" value={final.end_time} onChange={e=>setFinal({...final,end_time:e.target.value})}/></label><label>آجندا<textarea value={final.agenda} onChange={e=>setFinal({...final,agenda:e.target.value})}/></label><button className="button primary full" onClick={finalize}>ایجاد جلسهٔ رسمی</button></div>}</aside></div></> }

function MeetingDetail() { const id=location.pathname.split('/')[2]; const [m,setM]=useState<any>(null); useEffect(()=>{api.get(`/meetings/${id}`).then(r=>setM(apiData(r)))},[id]); if(!m)return <div className="screen-center"><div className="spinner"/></div>; return <><PageTitle eyebrow={m.meeting_number} title={m.title} description={`${m.request?.requesting_unit?.name||''} · جلسه رسمی`} action={<div className="page-actions">{m.reschedule_pending&&<span className="status pending">تغییر زمان در جریان است</span>}<span className="status approved">زمان‌بندی‌شده</span><a className="button primary" href={`/meetings/${id}/reschedule`}>تغییر زمان‌بندی</a><a className="button primary" href={`/meetings/${id}/participants/change`}>تغییر اشتراک‌کنندگان</a><a className="button secondary" href="/meetings">بازگشت به جلسات</a></div>}/><div className="detail-grid"><section className="detail-main"><div className="panel"><div className="detail-header"><div><span className="eyebrow">مشخصات جلسه</span><h2>{m.title}</h2></div><CalendarDays size={22}/></div><div className="info-grid"><div><span>شماره جلسه</span><strong className="mono">{m.meeting_number}</strong></div><div><span>ریاست برگزارکننده</span><strong>{m.request?.requesting_unit?.name||'—'}</strong></div><div><span>تاریخ</span><strong>{m.meeting_date?new Date(m.meeting_date).toLocaleDateString('fa-AF'):'—'}</strong></div><div><span>زمان</span><strong>{m.start_time} تا {m.end_time}</strong></div><div><span>محل</span><strong>{m.location||'—'}</strong></div><div><span>رئیس جلسه</span><strong>{m.chairperson?.full_name||'—'}</strong></div></div>{m.description&&<div className="description-block"><span>شرح</span><p>{m.description}</p></div>}{m.agenda&&<div className="description-block"><span>آجندا</span><p>{m.agenda}</p></div>}</div><div className="panel"><div className="panel-head"><div><span className="eyebrow">اشتراک‌کنندگان</span><h2>فهرست اشتراک‌کنندگان جلسه</h2></div><Users size={20}/></div><div className="people-list">{(m.participants||[]).map((p:any)=><div className="person-row" key={p.id}><div className="avatar tiny">{p.employee?.full_name?.slice(0,1)}</div><div><strong>{p.employee?.full_name}</strong><span>{p.employee?.unit?.name}</span></div><span className="tag">{p.role||'اشتراک‌کننده'}</span></div>)}</div>{!(m.participants||[]).length&&<EmptyState text="اشتراک‌کننده‌ای ثبت نشده است."/>}</div></section><aside className="detail-side"><div className="panel timeline"><div className="panel-head"><div><span className="eyebrow">مرجع گردش کار</span><h3>خط زمانی درخواست</h3></div><Clock3 size={19}/></div>{(m.request?.actions||[]).map((a:any)=><div className="timeline-item" key={a.id}><div className="timeline-dot"/><div><strong>{a.action==='CREATED'?'درخواست ایجاد شد':a.action==='SUBMITTED'?'درخواست برای تأیید ارسال شد':a.action==='APPROVED'?'درخواست تأیید شد':a.action==='SCHEDULING_STARTED'?'زمان‌بندی آغاز شد':a.action==='SCHEDULE_CONFIRMED'?'زمان‌بندی نهایی شد':a.action==='MEETING_CREATED'?'جلسه ایجاد گردید':a.action}</strong><span>{a.actor?.name} · {new Date(a.created_at).toLocaleString('fa-AF')}</span></div></div>)}</div></aside></div></> }
function Meetings() { const [data,setData]=useState<any>({data:[]});useEffect(()=>{api.get('/meetings').then(r=>setData(apiPage(r)))},[]);return <><PageTitle eyebrow="تقویم رسمی" title="جلسات آینده" description="جلسات ایجادشده پس از نهایی‌شدن زمان‌بندی."/><div className="panel table-panel"><table><thead><tr><th>شماره جلسه</th><th>عنوان</th><th>تاریخ و ساعت</th><th>محل</th><th>رئیس جلسه</th><th>وضعیت</th></tr></thead><tbody>{(data.data||[]).map((m:any)=><tr key={m.id}><td className="mono">{m.meeting_number}</td><td><a className="table-link" href={`/meetings/${m.id}`}>{m.title}</a></td><td>{new Date(m.meeting_date).toLocaleDateString('fa-AF')} · {m.start_time}</td><td>{m.location}</td><td>{m.chairperson?.full_name}</td><td><span className="status approved">زمان‌بندی‌شده</span></td></tr>)}</tbody></table>{!(data.data||[]).length&&<EmptyState text="جلسه آینده‌ای ثبت نشده است."/>}</div></> }
function Notifications() { const [data,setData]=useState<any>({data:[]});useEffect(()=>{api.get('/notifications').then(r=>setData(apiPage(r)))},[]);return <><PageTitle eyebrow="مرکز پیام‌ها" title="اعلان‌ها" description="اعلان‌های مربوط به گردش کار درخواست‌ها و جلسات."/><div className="panel notification-list">{(data.data||[]).map((n:any)=><div className={`notification-row ${n.read_at?'read':''}`} key={n.id}><div className="notification-icon"><Bell size={18}/></div><div><strong>{n.title}</strong><p>{n.message}</p><small>{new Date(n.created_at).toLocaleString('fa-AF')}</small></div>{!n.read_at&&<span className="unread">جدید</span>}</div>)}{!(data.data||[]).length&&<EmptyState text="اعلان جدیدی ندارید."/>}</div></> }
function Organization() { const [units,setUnits]=useState<any[]>([]);useEffect(()=>{api.get('/organizational-units').then(r=>setUnits(apiData(r)))},[]);return <><PageTitle eyebrow="مدیریت منابع" title="ساختار تشکیلاتی" description="ساختار سلسله‌مراتبی سازمان و ریاست‌های فعال."/><div className="org-grid">{units.filter(u=>!u.parent_id).map(u=><div className="org-tree panel" key={u.id}><div className="org-root"><Building2 size={20}/><div><strong>{u.name}</strong><span>{u.code} · ریاست</span></div></div><div className="org-children">{units.filter(c=>c.parent_id===u.id).map(c=><div className="org-child" key={c.id}><Network size={16}/><div><strong>{c.name}</strong><span>{c.unit_type==='MANAGEMENT'?'مدیریت اجرائیه':'دیپارتمنت'} · {c.code}</span></div></div>)}</div></div>)}</div></> }
function Employees() { const [employees,setEmployees]=useState<any[]>([]);useEffect(()=>{api.get('/employees').then(r=>setEmployees(apiData(r)))},[]);return <><PageTitle eyebrow="مدیریت منابع انسانی" title="کارمندان" description="فهرست کارمندان فعال سازمان."/><div className="panel table-panel"><table><thead><tr><th>شماره کارمندی</th><th>نام و نام خانوادگی</th><th>ریاست / واحد</th><th>سمت</th><th>وضعیت</th></tr></thead><tbody>{employees.map(e=><tr key={e.id}><td className="mono">{e.employee_number}</td><td><div className="person-cell"><div className="avatar tiny">{e.full_name.slice(0,1)}</div>{e.full_name}</div></td><td>{e.unit?.name}</td><td>{e.position?.title||'—'}</td><td><span className="status approved">فعال</span></td></tr>)}</tbody></table></div></> }
function App() { return <AuthProvider><Routes><Route path="/login" element={<Login/>}/><Route path="*" element={<Protected><Shell><Routes><Route path="/dashboard" element={<Dashboard/>}/><Route path="/meeting-requests" element={<Requests/>}/><Route path="/meeting-requests/create" element={<CreateRequest/>}/><Route path="/meeting-requests/create-inter-directorate" element={<CreateInterDirectorateRequest/>}/><Route path="/meeting-requests/create-multi-directorate" element={<CreateMultiDirectorate/>}/><Route path="/meeting-requests/create-high-authority" element={<CreateHighAuthority/>}/><Route path="/meeting-requests/create-multi-high-authority" element={<CreateMultiHighAuthority/>}/><Route path="/meeting-requests/create-authority-initiated" element={<CreateAuthorityInitiated/>}/>
<Route path="/incoming-meeting-requests" element={<IncomingRequests/>}/><Route path="/incoming-high-authority" element={<HighAuthorityInbox/>}/><Route path="/incoming-multi-high-authority" element={<MultiHighAuthorityInbox/>}/><Route path="/incoming-authority-initiated" element={<AuthorityInitiatedInbox/>}/><Route path="/meeting-requests/:id" element={<RequestDetail/>}/><Route path="/meeting-requests/:id/scheduling" element={<Scheduling/>}/><Route path="/meeting-requests/:id/multi-scheduling" element={<MultiDirectorateScheduling/>}/><Route path="/meeting-requests/:id/high-authority-scheduling" element={<HighAuthorityScheduling/>}/><Route path="/meeting-requests/:id/multi-high-scheduling" element={<MultiHighAuthorityScheduling/>}/><Route path="/meeting-requests/:id/authority-initiated-scheduling" element={<AuthorityInitiatedScheduling/>}/>
<Route path="/approvals" element={<Approvals/>}/><Route path="/meetings" element={<Meetings/>}/><Route path="/meetings/:id/reschedule" element={<MeetingRescheduleWorkspace/>}/><Route path="/meetings/:id/participants/change" element={<MeetingParticipantChangeWorkspace/>}/><Route path="/meetings/:id" element={<MeetingDetail/>}/><Route path="/notifications" element={<Notifications/>}/><Route path="/admin/organization" element={<Organization/>}/><Route path="/admin/employees" element={<Employees/>}/><Route path="/admin/roles" element={<Employees/>}/><Route path="/" element={<Navigate to="/dashboard" replace/>}/></Routes></Shell></Protected>}/></Routes></AuthProvider> }
ReactDOM.createRoot(document.getElementById('root')!).render(<React.StrictMode><BrowserRouter><App/></BrowserRouter></React.StrictMode>)
